-- ============================================================================
-- Datos de ejemplo (DML) — Sistema de gestión de caja y proveedores
-- PostgreSQL. Se ejecuta DESPUÉS de crear las tablas (python manage.py migrate).
--
-- Qué carga: 3 sedes (+1 dada de baja), 5 usuarios (administración, compras y un cajero
-- por sede), 6 proveedores (1 dado de baja), cajas cerradas de los últimos 6 días con sus
-- comprobantes e ítems, cajas abiertas hoy en 2 sedes, y pedidos en los tres estados.
-- Las fechas son relativas al día en que se ejecuta el script.
--
-- Contraseña de TODOS los usuarios de ejemplo:  Demo-1234
-- (solo para pruebas y demostración: NO usar en un sistema real)
--
-- Se ejecuta UNA sola vez, en una base sin sedes, proveedores, cajas, comprobantes ni
-- pedidos; si ya hay datos, se detiene sin cambiar nada. Para borrar los datos de ejemplo
-- y volver a empezar, usar limpiar_datos_ejemplo.sql.
-- Los usuarios que ya existan (por ejemplo el superusuario) no se tocan.
-- ============================================================================

BEGIN;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM sede) OR EXISTS (SELECT 1 FROM proveedor) OR EXISTS (SELECT 1 FROM caja)
       OR EXISTS (SELECT 1 FROM comprobante) OR EXISTS (SELECT 1 FROM pedido) THEN
        RAISE EXCEPTION 'La base ya tiene sedes, proveedores, cajas, comprobantes o pedidos. Para cargar los datos de ejemplo, primero ejecutar limpiar_datos_ejemplo.sql';
    END IF;
    IF EXISTS (SELECT 1 FROM usuario WHERE email LIKE '%@comedores.test') THEN
        RAISE EXCEPTION 'Ya existen usuarios @comedores.test. Ejecutar primero limpiar_datos_ejemplo.sql';
    END IF;
END $$;

-- Sedes

-- Usuarios (contraseña de todos: Demo-1234)

-- Proveedores

-- Cajas (cerradas: los últimos 6 días; abiertas: hoy, en las sedes 1 y 2)

-- Comprobantes de venta

-- Ítems de los comprobantes (algunos comprobantes se cargan solo con el monto total)

-- Pedidos a proveedores (cargados por el encargado de compras)


-- Se reajustan los contadores de id para que las altas nuevas (desde la API) sigan después de estos datos.
SELECT setval(pg_get_serial_sequence('sede', 'id'), (SELECT COALESCE(MAX(id), 1) FROM sede));
SELECT setval(pg_get_serial_sequence('usuario', 'id'), (SELECT COALESCE(MAX(id), 1) FROM usuario));
SELECT setval(pg_get_serial_sequence('proveedor', 'id'), (SELECT COALESCE(MAX(id), 1) FROM proveedor));
SELECT setval(pg_get_serial_sequence('caja', 'id'), (SELECT COALESCE(MAX(id), 1) FROM caja));
SELECT setval(pg_get_serial_sequence('comprobante', 'id'), (SELECT COALESCE(MAX(id), 1) FROM comprobante));
SELECT setval(pg_get_serial_sequence('item_comprobante', 'id'), (SELECT COALESCE(MAX(id), 1) FROM item_comprobante));
SELECT setval(pg_get_serial_sequence('pedido', 'id'), (SELECT COALESCE(MAX(id), 1) FROM pedido));
SELECT setval(pg_get_serial_sequence('item_pedido', 'id'), (SELECT COALESCE(MAX(id), 1) FROM item_pedido));

COMMIT;
